#!/usr/bin/env bash
# SAHA_HAFIZA_V4 (FULL) deploy — hafiza helper'lari + V4 (insan sesi, cross-bolge baglanti, izleme gizli) TEK yamada.
#   Sunucu hangi surumde olursa olsun (V2/V2B) dogrudan V4'e gecer. CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok"; exit 1; }
TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"; echo "yedek: $SRV.bak.$TS"
printf '%s' '' | base64 -d > /tmp/patch_saha_hafiza_v4_full.py
python3 /tmp/patch_saha_hafiza_v4_full.py "$SRV"
if ! node --check "$SRV"; then echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1; fi
echo "node --check: OK"
cp shells/kokpit2.html "shells/kokpit2.html.bak.$TS"
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "kokpit2.html satir: $(wc -l < shells/kokpit2.html)"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
docker exec krb-assessment sh -c "grep -c 'SAHA_HAFIZA_V4' /app/server.mjs" || true
echo "== /api/bi/kokpit2 -> Bolum 05: izleme paneli yok; farkli sehir/temsilci sinyallerini birlestiren insan-dili analist. =="
echo "== DONE =="
